\title{A Compact Algebraic Core for Four-Dimensional Geometry}
\author{Aristotle}
\date{July 12, 2026}

\begin{document}
\begin{abstract}
We show that four apparently independent constructions in four-dimensional
geometry --- the canonical fixed-point-free complex structure on $\mathbb{R}^4$,
the Hopf fibration of the three-sphere, the balanced radii of the Clifford torus,
and the interplay between the volume of the four-ball and the surface measure of
the three-sphere --- are all governed by a single sum-of-squares identity,
$(a+b)^2 = 4ab + (a-b)^2$. Alongside this continuous core we isolate a discrete
companion, the binomial identity $\sum_{k=0}^{n}(-1)^k\binom{n}{k}2^{\,n-k}=1$,
from which the Euler characteristic $1-(-1)^n$ of the boundary of the $n$-cube
follows immediately. We give precise statements and self-contained proofs of each
result, explain the odd-dimensional eigenvalue obstruction concretely, and outline
higher-dimensional extensions.
\end{abstract}

\maketitle

\section{Introduction}
Four-dimensional geometry is celebrated for phenomena with no lower-dimensional
analogue: rotations without an axis, the linking of the Hopf fibers, and the
peculiar arithmetic of higher-dimensional volumes. The purpose of this paper is to
expose a common algebraic spine. Our central observation is elementary but
organizing: the identity
\begin{equation}\label{eq:core}
(a+b)^2 = 4ab + (a-b)^2 \tag{$\star$}
\end{equation}
relates a product $4ab$, a squared difference $(a-b)^2$, and a squared sum
$(a+b)^2$ --- precisely the quantities arising when one computes squared norms,
area products, and radius constraints in four dimensions. Its discrete counterpart,
the binomial theorem specialized to $(2-1)^n$, governs the combinatorics of the
hypercube. Throughout, $\mathbb{R}^4$ carries the standard Euclidean structure and
$\mathbb{C}^2$ is identified with $\mathbb{R}^4$ in the usual way.

\section{The algebraic core}
\begin{lemma}[Sum-of-squares core]\label{lem:core}
For all real numbers $a,b$, $(a+b)^2 = 4ab + (a-b)^2$.
\end{lemma}
\begin{proof}
Both sides expand to $a^2 + 2ab + b^2$.
\end{proof}

\begin{lemma}[Alternating binomial identity]\label{lem:binom}
For every $n \ge 0$, $\displaystyle\sum_{k=0}^{n} (-1)^k \binom{n}{k}\, 2^{\,n-k} = 1$.
\end{lemma}
\begin{proof}
By the binomial theorem $\sum_{k=0}^n \binom{n}{k} x^k y^{n-k} = (x+y)^n$, set
$x=-1$ and $y=2$ to get $(2-1)^n = 1$.
\end{proof}

\section{The canonical complex structure on $\mathbb{R}^4$}
Write $\lVert x\rVert^2 = x_1^2 + x_2^2 + x_3^2 + x_4^2$ for
$x = (x_1,x_2,x_3,x_4)$.

\begin{definition}
The \emph{canonical complex structure} $J:\mathbb{R}^4\to\mathbb{R}^4$ is
$J(x_1,x_2,x_3,x_4) = (-x_2,\,x_1,\,-x_4,\,x_3)$, a simultaneous quarter-turn in
the $(x_1,x_2)$- and $(x_3,x_4)$-planes.
\end{definition}

\begin{theorem}[Complex structure]
$J^2 = -I$; that is, $J(J(x)) = -x$ for all $x$.
\end{theorem}
\begin{proof}
$J(J(x_1,x_2,x_3,x_4)) = J(-x_2,x_1,-x_4,x_3) = (-x_1,-x_2,-x_3,-x_4) = -x$.
\end{proof}

\begin{theorem}[Isometry]
$\lVert J(x)\rVert^2 = \lVert x\rVert^2$ for all $x$.
\end{theorem}
\begin{proof}
$\lVert J(x)\rVert^2 = (-x_2)^2 + x_1^2 + (-x_4)^2 + x_3^2 = \lVert x\rVert^2$.
\end{proof}

\begin{theorem}[Fixed-point freeness]
If $J(x)=x$ then $x=0$; hence $J$ acts without fixed points on
$S^3=\{\lVert x\rVert^2 = 1\}$.
\end{theorem}
\begin{proof}
$J(x)=x$ gives $-x_2=x_1$, $x_1=x_2$, $-x_4=x_3$, $x_3=x_4$. The first two force
$x_1=x_2=0$, and similarly $x_3=x_4=0$, so $x=0$. If $\lVert x\rVert^2=1$ there is
no solution.
\end{proof}

\begin{remark}[The odd-dimensional obstruction]
A linear isometry acts freely on the surrounding odd sphere precisely when it lacks
the eigenvalue $1$, i.e.\ when $J-I$ is invertible. The identity $Jx=x\Rightarrow
x=0$ says exactly that $J-I$ has trivial kernel. In odd-dimensional spaces no such
$J$ exists: a real operator on an odd-dimensional space has a real eigenvalue, and
an isometry's only real eigenvalues are $\pm1$, forcing a fixed direction whenever
$+1$ occurs. The evenness of $4$ permits the fixed-point-free quarter-turn.
\end{remark}

\section{The Hopf map}
Identify $\mathbb{R}^4\cong\mathbb{C}^2$ via $(z,w)$.
\begin{definition}
The \emph{Hopf map} $H:\mathbb{C}^2\to\mathbb{C}\times\mathbb{R}$ is
$H(z,w) = (2z\overline{w},\ |z|^2-|w|^2)$.
\end{definition}

\begin{theorem}[Circle invariance]
For every $\lambda\in\mathbb{C}$ with $|\lambda|^2=1$,
$H(\lambda z,\lambda w) = H(z,w)$; the fibers of $H$ are the diagonal circle
orbits.
\end{theorem}
\begin{proof}
First coordinate: $2(\lambda z)\overline{(\lambda w)} =
2|\lambda|^2 z\overline{w} = 2z\overline{w}$. Second coordinate:
$|\lambda z|^2 - |\lambda w|^2 = |\lambda|^2(|z|^2-|w|^2) = |z|^2-|w|^2$.
\end{proof}

Since multiplication by $\lambda=i$ realizes $J$, the Hopf circle action is
generated by $J$.

\begin{theorem}[Image sphere]
For all $z,w$,
$|2z\overline{w}|^2 + (|z|^2-|w|^2)^2 = (|z|^2+|w|^2)^2$; on the unit sphere the
image lies on the unit two-sphere.
\end{theorem}
\begin{proof}
Since $|2z\overline{w}|^2 = 4|z|^2|w|^2$, with $a=|z|^2$, $b=|w|^2$ the claim is
$4ab+(a-b)^2=(a+b)^2$, which is Lemma~\ref{lem:core}.
\end{proof}

\section{The Clifford torus}
Consider the flat-torus family in $S^3$,
$(\theta,\varphi)\mapsto(r_1\cos\theta,r_1\sin\theta,r_2\cos\varphi,r_2\sin\varphi)$
with $r_1^2+r_2^2=1$; its area is governed by $4r_1^2r_2^2$. Put $a=r_1^2$,
$b=r_2^2$, so $a+b=1$.

\begin{theorem}[Clifford balance]
If $a+b=1$ then $4ab = 1-(a-b)^2$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:core}, $4ab = (a+b)^2 - (a-b)^2 = 1-(a-b)^2$.
\end{proof}

\begin{theorem}[Upper bound]
If $a+b=1$ then $4ab\le1$.
\end{theorem}
\begin{proof}
$4ab = 1-(a-b)^2 \le 1$ since $(a-b)^2\ge0$.
\end{proof}

\begin{theorem}[Extremal balance]
If $a+b=1$ then $4ab=1$ if and only if $a=b$.
\end{theorem}
\begin{proof}
$4ab=1 \iff (a-b)^2=0 \iff a=b$.
\end{proof}

Thus the area is maximized uniquely at $r_1^2=r_2^2=\tfrac12$, the balanced
Clifford torus $r_1=r_2=1/\sqrt2$; balance is also exactly invariance under the
diagonal circle action.

\section{Volume of the four-ball and surface of the three-sphere}
\begin{theorem}[Volume--surface derivative]
Let $V(r)=\frac{\pi^2}{2}r^4$ be the volume of the four-ball of radius $r$. Then
$V'(r)=2\pi^2 r^3$, the surface measure of the bounding three-sphere.
\end{theorem}
\begin{proof}
$V'(r) = \frac{\pi^2}{2}\cdot 4r^3 = 2\pi^2 r^3$, and the surface measure of
$S^3_r$ is $2\pi^2 r^3$.
\end{proof}

This is the four-dimensional instance of $\frac{d}{dr}\mathrm{Vol}(B_r) =
\mathrm{Area}(\partial B_r)$; the constant $\pi^2/2 = \pi^2/2!$ is dictated by the
Gamma-function volume formula in even dimension.

\section{The hypercube and its boundary Euler characteristic}
The $n$-cube $[0,1]^n$ has $\binom{n}{k}2^{\,n-k}$ faces of dimension $k$.

\begin{theorem}[Total alternating face sum]
$\displaystyle\sum_{k=0}^{n}(-1)^k\binom{n}{k}2^{\,n-k} = 1$.
\end{theorem}
\begin{proof}
This is Lemma~\ref{lem:binom}.
\end{proof}

\begin{theorem}[Boundary Euler characteristic]
The boundary $\partial[0,1]^n$, a topological $(n-1)$-sphere, has Euler
characteristic $1-(-1)^n$.
\end{theorem}
\begin{proof}
Subtract the top cell's contribution $(-1)^n$ from the total $1$.
\end{proof}

For even $n$ this is $0$; for odd $n$ it is $2$, matching $\chi(S^{n-1})$.

\section{Discussion and future work}
The unifying lesson is that these ``exotic'' four-dimensional objects are shadows
of two schoolbook identities: the sum-of-squares identity~\eqref{eq:core} on the
continuous side and the binomial theorem on the discrete side. We highlight several
conjectural extensions.
\begin{enumerate}
\item On $\mathbb{R}^{2n}$ the coordinate-pairing quarter-turn is conjecturally the
unique isometry (up to orthogonal conjugacy) whose square is central and which acts
freely on $S^{2n-1}$; every fixed-point-free linear isometry of an odd sphere
should be a block sum of planar rotations.
\item On $S^{2m-1}$ with $\sum r_i^2=1$, the symmetric point $r_i^2=1/m$ should be
the unique critical point of the product functional and the unique embedding
invariant under the diagonal circle action.
\item The value $1-(-1)^n$ should govern the boundary of every simple $n$-polytope,
independent of combinatorial type.
\item The diagonal circle should be the maximal connected subgroup of $SO(4)$
acting freely on $S^3$ with the Hopf fibers as orbits, with centralizer $U(2)$.
\item The constant $\pi^2/2$ should be the extremal ratio of a sharp
four-dimensional isoperimetric inequality.
\end{enumerate}

\end{document}

