from typing import Tuple

def clifford_product(a: float) -> float:
    """4 a b with b = 1 - a; on a+b=1 this equals 1 - (a-b)^2."""
    b = 1.0 - a
    return 4 * a * b

def optimize() -> Tuple[float, float]:
    best_a, best_val = 0.0, -1.0
    for i in range(1, 10000):
        a = i / 10000.0
        v = clifford_product(a)
        if v > best_val:
            best_val, best_a = v, a
    return best_a, best_val

if __name__ == "__main__":
    a, v = optimize()
    print(f"argmax r1^2 = {a:.4f} (exact 0.5), max 4 r1^2 r2^2 = {v:.6f} (exact 1.0)")

from math import comb, pi

def cube_alternating_face_sum(n: int) -> int:
    """sum_k (-1)^k C(n,k) 2^(n-k) = (2-1)^n = 1."""
    return sum((-1) ** k * comb(n, k) * 2 ** (n - k) for k in range(n + 1))

def cube_boundary_euler(n: int) -> int:
    return cube_alternating_face_sum(n) - (-1) ** n

def ball4_volume(r: float) -> float:
    return (pi ** 2 / 2) * r ** 4

def sphere3_surface(r: float) -> float:
    return 2 * pi ** 2 * r ** 3

if __name__ == "__main__":
    for n in range(1, 7):
        print(f"n={n}: face sum={cube_alternating_face_sum(n)}, "
              f"boundary chi={cube_boundary_euler(n)}")
    r = 2.0
    print(f"V(2)={ball4_volume(r):.4f}, S(2)={sphere3_surface(r):.4f}")

