function CliffordOptimal(steps):
    best_a <- 0; best_val <- -inf
    for i in 1 .. steps-1:
        a   <- i / steps
        val <- 4 * a * (1 - a)        # = 1 - (2a-1)^2
        if val > best_val:
            best_val <- val; best_a <- a
    return (best_a, 1 - best_a, best_val)  # -> (1/2, 1/2, 1)

