def clifford_optimal_radii(steps: int = 100000) -> tuple[float, float, float]:
    """Return (r1_squared, r2_squared, max_product) maximizing 4 r1^2 r2^2
    on r1^2 + r2^2 = 1 by exhaustive one-parameter search."""
    best_a, best_val = 0.0, -1.0
    for i in range(1, steps):
        a = i / steps
        val = 4 * a * (1 - a)  # = 1 - (a - (1-a))^2
        if val > best_val:
            best_val, best_a = val, a
    return best_a, 1 - best_a, best_val

