function BoundaryEuler(n):
    total <- 0
    for k in 0 .. n:
        f_k   <- C(n,k) * 2^(n-k)     # count of k-faces
        total <- total + (-1)^k * f_k # -> 1 by binomial theorem
    return total - (-1)^n             # remove top cell -> 1 - (-1)^n

