from math import comb

def cube_face_counts(n: int) -> list[int]:
    """f_k = C(n,k) * 2^(n-k), the number of k-faces of the n-cube."""
    return [comb(n, k) * 2 ** (n - k) for k in range(n + 1)]

def alternating_face_sum(n: int) -> int:
    """sum_k (-1)^k f_k = (2-1)^n = 1."""
    return sum((-1) ** k * f for k, f in enumerate(cube_face_counts(n)))

def boundary_euler_characteristic(n: int) -> int:
    """chi(boundary of n-cube) = total sum minus the top cell = 1 - (-1)^n."""
    return alternating_face_sum(n) - (-1) ** n
